{
  "patient": {
    "name": "Maria Delgado",
    "birthdate": "1958-03-14",
    "source": "p1:L3"
  },
  "diagnoses": [
    {
      "text": "Total knee arthroplasty (right knee)",
      "source": "p1:L4"
    }
  ],
  "medications": [
    {
      "name": "Oxycodone",
      "dose": "5 mg",
      "freq": "q4h PRN",
      "status": "continued",
      "instructions": "Do not drive while taking. For moderate to severe pain.",
      "source": "p1:L6"
    },
    {
      "name": "Tylenol",
      "dose": "1,000 mg",
      "freq": "q8h scheduled",
      "status": "new",
      "instructions": "Take scheduled for 2 weeks",
      "source": "p1:L7"
    },
    {
      "name": "Enoxaparin",
      "dose": "40 mg",
      "freq": "once daily",
      "status": "new",
      "instructions": "SubQ x 14 days for blood clot prevention",
      "source": "p1:L8"
    },
    {
      "name": "Docusate",
      "dose": "100 mg",
      "freq": "BID",
      "status": "continued",
      "instructions": "While taking oxycodone",
      "source": "p1:L9"
    },
    {
      "name": "Ondansetron",
      "dose": "4 mg",
      "freq": "q8h PRN",
      "status": "continued",
      "instructions": "For nausea",
      "source": "p1:L10"
    }
  ],
  "follow_ups": [
    {
      "who": "Orthopedics",
      "when": "2 weeks for staple removal",
      "source": "p1:L13"
    }
  ],
  "warning_signs": [
    {
      "text": "Chest pain or sudden shortness of breath - call 911 or go to ED",
      "source": "p1:L14"
    },
    {
      "text": "Calf pain or swelling in either leg - call the surgeon",
      "source": "p1:L16"
    },
    {
      "text": "Fever over 101.5 F - call the surgeon",
      "source": "p1:L17"
    },
    {
      "text": "Redness, warmth or drainage from the incision - call the surgeon",
      "source": "p1:L18"
    }
  ],
  "restrictions": [
    {
      "text": "Do not drive while taking oxycodone",
      "source": "p1:L6"
    },
    {
      "text": "Keep dressing dry. No tub baths or swimming until staples are removed",
      "source": "p1:L12"
    },
    {
      "text": "Weight bearing as tolerated with walker. Physical therapy 3 times per week. Ice 20 minutes every 2 hours. Keep leg elevated",
      "source": "p1:L11"
    }
  ],
  "unknown_terms": [
    "PRN",
    "PO",
    "q4h",
    "q8h",
    "subQ",
    "BID",
    "WBAT",
    "PT",
    "ED",
    "TKA"
  ],
  "uncertain": []
}
